<?php $title='Customer Dashboard';require __DIR__.'/../includes/header.php';require_login('customer');require __DIR__.'/../config/database.php';$st=$pdo->prepare("SELECT r.*,s.name category,pr.name province,d.name district,c.name city,p.payment_status,p.amount,v.brand,v.model,v.registration_number,v.vehicle_type FROM assistance_requests r JOIN service_categories s ON s.id=r.category_id LEFT JOIN provinces pr ON pr.id=r.province_id LEFT JOIN districts d ON d.id=r.district_id LEFT JOIN cities c ON c.id=r.city_id LEFT JOIN payments p ON p.request_id=r.id LEFT JOIN vehicles v ON v.id=r.vehicle_id WHERE r.customer_id=? ORDER BY r.created_at DESC");$st->execute([$_SESSION['user_id']]);$rows=$st->fetchAll();?>
<section class="section-pad"><div class="container"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="fw-bold">Hello, <?=e($_SESSION['name'])?></h1><p class="text-muted">Manage your INFINEX assistance requests.</p></div><a href="vehicle-details.php" class="btn btn-warning fw-bold">New Assistance</a></div><div class="card border-0 shadow-sm rounded-4"><div class="card-body"><h5 class="fw-bold">Request history</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Vehicle</th><th>Service</th><th>Location</th><th>Status</th><th>Fee</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(trim(($r['brand']??'').' '.($r['model']??'')))?><?php if(!empty($r['registration_number'])):?><br><small class="text-muted"><?=e($r['registration_number'])?></small><?php endif;?></td><td><?=e($r['category'])?></td><td><?=e($r['address'] ?: 'Exact location')?></td><td><span class="badge text-bg-<?=($r['payment_status']==='success'?'success':'secondary')?>"><?=e($r['status'])?></span></td><td>Rs. <?=number_format((float)($r['amount']??0),2)?></td><td><?php if($r['payment_status']==='success'):?><a class="btn btn-sm btn-dark" href="providers.php?request=<?=$r['id']?>">Providers</a><?php else: ?><a class="btn btn-sm btn-warning" href="payment.php?request=<?=$r['id']?>">Pay</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>